cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fixed problem sizes for this specific model:
//   Cin = 3, Cout = 32, K = 3, stride = 1, padding = 0, dilation = 1
__host__ __device__ constexpr int CIN  = 3;
__host__ __device__ constexpr int COUT = 32;
__host__ __device__ constexpr int KH   = 3;
__host__ __device__ constexpr int KW   = 3;

constexpr int TILE_OH = 16;
constexpr int TILE_OW = 64;
constexpr int OW_PER_THREAD = 4;
constexpr int OH_PER_THREAD = 2;
constexpr int THREADS = (TILE_OH / OH_PER_THREAD) * (TILE_OW / OW_PER_THREAD); // 128, larger CTA tile with more warps/block for better latency hiding and amortized weight staging

constexpr int SIN_H = TILE_OH + KH - 1; // 10
constexpr int SIN_W = TILE_OW + KW - 1; // 34

__global__ void conv2d_3x3_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    int N, int Hin, int Win, int Hout, int Wout)
{
    const int tid = threadIdx.x;
    const int n   = blockIdx.z;

    const int tile_oh = blockIdx.y;
    const int tile_ow = blockIdx.x;

    const int oh_base = tile_oh * TILE_OH;
    const int ow_base = tile_ow * TILE_OW;

    // Per-batch global tensors
    int64_t sXn = (int64_t)CIN * Hin * Win;
    int64_t sYn = (int64_t)COUT * Hout * Wout;

    Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                             make_shape(CIN, Hin, Win),
                             make_stride((int64_t)Hin * Win, (int64_t)Win, (int64_t)1));

    Tensor mW = make_tensor(make_gmem_ptr(W),
                             make_shape(COUT, CIN, KH, KW),
                             make_stride(CIN * KH * KW, KH * KW, KW, 1));

    Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                             make_shape(COUT, Hout, Wout),
                             make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

    // Shared memory: input tile (CIN, SIN_H, SIN_W) and full weights (COUT, CIN, KH, KW)
    __shared__ __nv_bfloat16 sX_raw[CIN * SIN_H * SIN_W];
    __shared__ __nv_bfloat16 sW_raw[COUT * CIN * KH * KW];

    Tensor sX = make_tensor(make_smem_ptr(sX_raw),
                             make_shape(Int<CIN>{}, Int<SIN_H>{}, Int<SIN_W>{}),
                             make_stride(Int<SIN_H * SIN_W>{}, Int<SIN_W>{}, Int<1>{}));

    Tensor sW = make_tensor(make_smem_ptr(sW_raw),
                             make_shape(Int<COUT>{}, Int<CIN>{}, Int<KH>{}, Int<KW>{}),
                             make_stride(Int<CIN * KH * KW>{}, Int<KH * KW>{}, Int<KW>{}, Int<1>{}));

    // Load input tile into shared memory
    constexpr int SIN_TOTAL = CIN * SIN_H * SIN_W;
    for (int idx = tid; idx < SIN_TOTAL; idx += THREADS) {
        int ic = idx / (SIN_H * SIN_W);
        int rem = idx - ic * (SIN_H * SIN_W);
        int ih_l = rem / SIN_W;
        int iw_l = rem - ih_l * SIN_W;

        int ih = oh_base + ih_l;
        int iw = ow_base + iw_l;

        __nv_bfloat16 val = __float2bfloat16(0.0f);
        if (ih < Hin && iw < Win) {
            val = mX(ic, ih, iw);
        }
        sX(ic, ih_l, iw_l) = val;
    }

    // Load weights into shared memory
    constexpr int W_TOTAL = COUT * CIN * KH * KW;
    for (int idx = tid; idx < W_TOTAL; idx += THREADS) {
        int oc = idx / (CIN * KH * KW);
        int rem = idx - oc * (CIN * KH * KW);
        int ic = rem / (KH * KW);
        rem = rem - ic * (KH * KW);
        int kh = rem / KW;
        int kw = rem - kh * KW;
        sW(oc, ic, kh, kw) = mW(oc, ic, kh, kw);
    }

    __syncthreads();

    // Compute output
    // Each thread computes an OH_PER_THREAD x OW_PER_THREAD block of adjacent
    // outputs, reusing each loaded weight value across all of them
    // (2D register blocking over both output height and width).
    constexpr int OW_GROUPS = TILE_OW / OW_PER_THREAD;
    int local_oh_group = tid / OW_GROUPS;
    int local_ow0       = (tid - local_oh_group * OW_GROUPS) * OW_PER_THREAD;
    int local_oh_base   = local_oh_group * OH_PER_THREAD;
    int ow0 = ow_base + local_ow0;
    // Precompute input register cache once per thread: reused across all COUT
    // output channels, eliminating redundant shared-memory reads and bf16->float
    // conversions that previously happened COUT (32) times for the same value.
    float sx_reg[OH_PER_THREAD][CIN][KH][KW][OW_PER_THREAD];
    #pragma unroll
    for (int r = 0; r < OH_PER_THREAD; ++r) {
        int local_oh = local_oh_base + r;
        #pragma unroll
        for (int ic = 0; ic < CIN; ++ic) {
            #pragma unroll
            for (int kh = 0; kh < KH; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < KW; ++kw) {
                    #pragma unroll
                    for (int j = 0; j < OW_PER_THREAD; ++j) {
                        sx_reg[r][ic][kh][kw][j] = __bfloat162float(sX(ic, local_oh + kh, local_ow0 + j + kw));
                    }
                }
            }
        }
    }
    #pragma unroll
    for (int oc = 0; oc < COUT; ++oc) {
        float acc[OH_PER_THREAD][OW_PER_THREAD];
        #pragma unroll
        for (int r = 0; r < OH_PER_THREAD; ++r) {
            #pragma unroll
            for (int j = 0; j < OW_PER_THREAD; ++j) acc[r][j] = 0.0f;
        }
        #pragma unroll
        for (int ic = 0; ic < CIN; ++ic) {
            #pragma unroll
            for (int kh = 0; kh < KH; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < KW; ++kw) {
                    float wv = __bfloat162float(sW(oc, ic, kh, kw));
                    #pragma unroll
                    for (int r = 0; r < OH_PER_THREAD; ++r) {
                        #pragma unroll
                        for (int j = 0; j < OW_PER_THREAD; ++j) {
                            acc[r][j] += sx_reg[r][ic][kh][kw][j] * wv;
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int r = 0; r < OH_PER_THREAD; ++r) {
            int oh = oh_base + local_oh_base + r;
            if (oh >= Hout) continue;
            __nv_bfloat16* yptr = &mY(oc, oh, ow0);
            bool can_vec2 = (ow0 + OW_PER_THREAD <= Wout) &&
                            ((reinterpret_cast<uintptr_t>(yptr) & 0x3) == 0);
            if (can_vec2) {
                __nv_bfloat162* yptr2 = reinterpret_cast<__nv_bfloat162*>(yptr);
                #pragma unroll
                for (int j = 0; j < OW_PER_THREAD; j += 2) {
                    __nv_bfloat162 v;
                    v.x = __float2bfloat16(acc[r][j]);
                    v.y = __float2bfloat16(acc[r][j + 1]);
                    yptr2[j / 2] = v;
                }
            } else {
                #pragma unroll
                for (int j = 0; j < OW_PER_THREAD; ++j) {
                    int ow = ow0 + j;
                    if (ow < Wout) {
                        mY(oc, oh, ow) = __float2bfloat16(acc[r][j]);
                    }
                }
            }
        }
    }
}

torch::Tensor conv2d_3x3_forward(torch::Tensor x, torch::Tensor weight) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
    TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
    TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
    TORCH_CHECK(weight.dim() == 4, "weight must be [Cout,Cin,KH,KW]");

    int64_t N   = x.size(0);
    int64_t C   = x.size(1);
    int64_t Hin = x.size(2);
    int64_t Win = x.size(3);

    TORCH_CHECK(C == CIN, "in_channels mismatch, expected 3");
    TORCH_CHECK(weight.size(0) == COUT, "out_channels mismatch, expected 32");
    TORCH_CHECK(weight.size(1) == CIN, "weight in_channels mismatch");
    TORCH_CHECK(weight.size(2) == KH && weight.size(3) == KW, "kernel size mismatch, expected 3x3");

    int64_t Hout = Hin - KH + 1;
    int64_t Wout = Win - KW + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto y = torch::empty({N, COUT, Hout, Wout}, x.options());

    dim3 block(THREADS);
    dim3 grid(
        (unsigned)((Wout + TILE_OW - 1) / TILE_OW),
        (unsigned)((Hout + TILE_OH - 1) / TILE_OH),
        (unsigned)N
    );

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_3x3_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
        (int)N, (int)Hin, (int)Win, (int)Hout, (int)Wout
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_3x3_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_3x3_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_3x3_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
